// Round-56 hang probe: non-suspending bounded try_wait; on give-up, lane 0 of
// the stuck warp prints the mbarrier offset inside the CTA-local mbar array,
// the waited phase, and RETURNS (breaks the deadlock so printf flushes and
// the kernel completes with garbage data). Compile-time only; never shipped.
extern __shared__ char kda_probe_smem[];
#endif
__device__ __forceinline__ void mbarrier_wait(int mbar_addr, int phase) {
#if defined(KDA_HANG_PROBE)
    uint32_t token = 0;
    for (unsigned long long _spin = 0; _spin < 8000000ULL; _spin++) {
        asm volatile(
            "{\n\t"
            ".reg .pred P1;\n\t"
            "mbarrier.try_wait.parity.acquire.cta.shared::cta.b64"
            " P1, [%1], %2, %3;\n\t"
            "selp.u32 %0, 1, 0, P1;\n\t"
            "}\n"
            : "=r"(token)
            : "r"(mbar_addr), "r"(phase), "r"(0) : "memory");
        if (token) return;
    }
    if (threadIdx.x % 32 == 0) {
        int _base = (int)__cvta_generic_to_shared(kda_probe_smem);
        printf("[HANGPROBE] cta=%d warp=%d mbr_off=%d phase=%d\n",
               (int)blockIdx.x, (int)(threadIdx.x >> 5), mbar_addr - _base, phase);
    }
    return;
#else
    uint32_t ticks = 0x989680;
    asm volatile(
        "{\n\t"
        ".reg .pred P1;\n\t"
        "LAB_WAIT:\n\t"
        "mbarrier.try_wait.parity.acquire.cta.shared::cta.b64"
        " P1, [%0], %1, %2;\n\t"
        "@P1 bra.uni DONE;\n\t"
        "bra.uni LAB_WAIT;\n\t"
        "DONE:\n\t"
        "}\n"
        :: "r"(mbar_addr), "r"(phase), "r"(ticks) : "memory");
#endif
}

