                    // Release c_p: the barrier above orders all 128 emit
                    // threads' carry stores before this thread's fence+flag
                    // (the CUB decoupled-lookback publication pattern; t=128
                    // sits in a non-matvec warp so the fence never stalls a
                    // row-lane warp's accumulation).
                    __threadfence();
                    atomicAdd(flagp + p, 1);
                }
                if (row_lane) {
                    #pragma unroll 8
                    for (int kp = 0; kp < 128; kp++) {
                        const float a = smem_cur[vl * CPAD + kp];
                        const float4 m4 = *reinterpret_cast<const float4*>(mbuf + kp * MPAD + kl * 4);
                        acc[0] = fmaf(a, m4.x, acc[0]);
                        acc[1] = fmaf(a, m4.y, acc[1]);
                        acc[2] = fmaf(a, m4.z, acc[2]);
                        acc[3] = fmaf(a, m4.w, acc[3]);
