    // CUDA kernel-start ordering does not acquire the tensor-map proxy.
    // One thread acquires each 128-byte map; the CTA barrier publishes those
    // acquires to every thread before any TMA instruction can use a map.
    if (threadIdx.x == 0) {
        asm volatile(
            "fence.proxy.tensormap::generic.acquire.gpu [%0], 128;\n"
            "fence.proxy.tensormap::generic.acquire.gpu [%1], 128;\n"
            "fence.proxy.tensormap::generic.acquire.gpu [%2], 128;\n"
            "fence.proxy.tensormap::generic.acquire.gpu [%3], 128;\n"
            "fence.proxy.tensormap::generic.acquire.gpu [%4], 128;\n"
            "fence.proxy.tensormap::generic.acquire.gpu [%5], 128;\n"
            :: "l"(q_tma), "l"(k_tma), "l"(v_tma), "l"(g_tma),
               "l"(beta_tma), "l"(out_tma)
            : "memory");
    }
    __syncthreads();
    // FLASHINFER INTEGRATION END: acquire global tensor maps
    const int tid = threadIdx.x;
    const int warp = make_warp_uniform(tid / 32);
    const int lane = tid % 32;

    extern __shared__ __align__(1024) char smem_raw[];
    int smem;
    smem = (int)(unsigned long long)__cvta_generic_to_shared(smem_raw);

    const int bid = blockIdx.x;
    const int num_bids = gridDim.x;
    // Split-seq part index: the main launch (fixup_mode 0) and map launch
    // (fixup_mode 2) assign blockIdx.y to parts [0, P); the correction launch
    // (fixup_mode 1) reuses blockIdx.y for parts [1, P). The round-48 fused
    // scan/correction launch (fixup_mode 3) reserves blockIdx.y [0, 32) for
    // the scan-band role (those CTAs returned above); correction CTAs remap
    // band y to part y-32+1.
    const int part_y = (int)blockIdx.y - ((fixup_mode == 3) ? 32 : 0);
    const int split_part = part_y + (((fixup_mode & 1) == 1) ? 1 : 0);

    // Kernel setup ops
    __nv_bfloat16* smem_qd = reinterpret_cast<__nv_bfloat16*>(smem_raw + 1024);
    const int smem_qd_addr = smem + 1024;
    __nv_bfloat16* smem_g_raw = reinterpret_cast<__nv_bfloat16*>(smem_raw + 1024);
    const int smem_g_raw_addr = smem + 1024;
    __nv_bfloat16* smem_g_raw_all = reinterpret_cast<__nv_bfloat16*>(smem_raw + 1024);
    const int smem_g_raw_all_addr = smem + 1024;
    __nv_bfloat16* smem_kd = reinterpret_cast<__nv_bfloat16*>(smem_raw + 9216);
    const int smem_kd_addr = smem + 9216;
    __nv_bfloat16* smem_q_raw_prefetch = reinterpret_cast<__nv_bfloat16*>(smem_raw + 17408);
    const int smem_q_raw_prefetch_addr = smem + 17408;
    __nv_bfloat16* smem_final_trans = reinterpret_cast<__nv_bfloat16*>(smem_raw + 17408);
    const int smem_final_trans_addr = smem + 17408;
    __nv_bfloat16* smem_kr_trans = reinterpret_cast<__nv_bfloat16*>(smem_raw + 17408);
    const int smem_kr_trans_addr = smem + 17408;
    __nv_bfloat16* smem_mqk_trans = reinterpret_cast<__nv_bfloat16*>(smem_raw + 25600);
    const int smem_mqk_trans_addr = smem + 25600;
#if defined(KDA_TF32_U2)
    __nv_bfloat16* smem_inv = reinterpret_cast<__nv_bfloat16*>(smem_raw + 37888);
    const int smem_inv_addr = smem + 37888;
#else
    __nv_bfloat16* smem_inv = reinterpret_cast<__nv_bfloat16*>(smem_raw + 29696);
    const int smem_inv_addr = smem + 29696;
#endif
#if defined(KDA_TF32_U2)
    __nv_bfloat16* smem_v = reinterpret_cast<__nv_bfloat16*>(smem_raw + 40576);
    const int smem_v_addr = smem + 40576;
#else
    __nv_bfloat16* smem_v = reinterpret_cast<__nv_bfloat16*>(smem_raw + 32384);
    const int smem_v_addr = smem + 32384;
#endif
    __nv_bfloat16* smem_ki = reinterpret_cast<__nv_bfloat16*>(smem_raw + 17408);
    const int smem_ki_addr = smem + 17408;
    float* smem_gate = reinterpret_cast<float*>(smem_raw + 25600);
    const int smem_gate_addr = smem + 25600;
    __nv_bfloat16* smem_beta_raw = reinterpret_cast<__nv_bfloat16*>(smem_raw + KDA_STAGE_BYTES);
    const int smem_beta_raw_addr = smem + KDA_STAGE_BYTES;
#if defined(KDA_TF32_U2)
    __nv_bfloat16* smem_inv_work = reinterpret_cast<__nv_bfloat16*>(smem_raw + 40576);
    const int smem_inv_work_addr = smem + 40576;
#else
    __nv_bfloat16* smem_inv_work = reinterpret_cast<__nv_bfloat16*>(smem_raw + 32384);
    const int smem_inv_work_addr = smem + 32384;
#endif
    __nv_bfloat16* smem_out = reinterpret_cast<__nv_bfloat16*>(smem_raw + SMEM_SMEM_OUT_OFF);
    const int smem_out_addr = smem + SMEM_SMEM_OUT_OFF;
    float* smem_restore_factor_all = reinterpret_cast<float*>(smem_raw + KDA_STAGE_BYTES);
    const int smem_restore_factor_all_addr = smem + KDA_STAGE_BYTES;
#if defined(KDA_TF32_U2)
    float* smem_gt_prefix_all = reinterpret_cast<float*>(smem_raw + 49664);
    const int smem_gt_prefix_all_addr = smem + 49664;
#else
    float* smem_gt_prefix_all = reinterpret_cast<float*>(smem_raw + 41472);
    const int smem_gt_prefix_all_addr = smem + 41472;
#endif
#if defined(KDA_TF32_U2)
    float* smem_gt_all = reinterpret_cast<float*>(smem_raw + 39936);
    const int smem_gt_all_addr = smem + 39936;
#else
    float* smem_gt_all = reinterpret_cast<float*>(smem_raw + 31744);
    const int smem_gt_all_addr = smem + 31744;
#endif
    float* smem_prep_beta_all = reinterpret_cast<float*>(smem_raw + KDA_STAGE_BYTES + 516);
    const int smem_prep_beta_all_addr = smem + KDA_STAGE_BYTES + 516;
    float* smem_gate_rate_all = reinterpret_cast<float*>(smem_raw + KDA_STAGE_BYTES + 644);
    const int smem_gate_rate_all_addr = smem + KDA_STAGE_BYTES + 644;
#if defined(KDA_PREP_PIPE2)
    // De-aliased restore_factor region (160 floats/stage): no longer shares
    // the beta_raw bytes, so the next chunk's beta TMA may land mid-body.
    float* smem_restore2_all = reinterpret_cast<float*>(smem_raw + (SMEM_TOTAL - 3712));
    const int smem_restore2_all_addr = smem + (SMEM_TOTAL - 3712);
#endif
#if defined(KDA_TF32_U2)
    __nv_bfloat16* smem_v_all = reinterpret_cast<__nv_bfloat16*>(smem_raw + 40576);
    const int smem_v_all_addr = smem + 40576;
#else
    __nv_bfloat16* smem_v_all = reinterpret_cast<__nv_bfloat16*>(smem_raw + 32384);
    const int smem_v_all_addr = smem + 32384;
#endif
    float* smem_gate_all = reinterpret_cast<float*>(smem_raw + 25600);
    const int smem_gate_all_addr = smem + 25600;

    // Mbarrier init (17 groups, 77 barriers)
    // Mbarriers at smem_raw[0..616)

    if (warp == 0 && lane == 0) {
        // Round-61: lane-parallel mbarrier init. The original code elected
        // one lane and issued all 120 mbarrier.init ops serially from it
        // (~120 dependent SMEM round-trips ~ 1-1.4us of kernel prologue that
        // sits on the critical path up to the first __syncthreads()). Each
        // lane now handles the init whose flat index matches lane+32*j;
        // correctness is unchanged because init order is irrelevant and the
        // existing fence.mbarrier_init + __syncthreads() below publishes
        // every lane's stores to the whole CTA.
        // Round-62: REVERTED the R61 lane-parallel mbarrier init (measured
        // no wall-time win; supervisor REDIRECT): single elected lane again.
        # define mbarrier_init_r61(addr, cnt) \
            mbarrier_init_pred((addr), (cnt), true)
        // --- pipeline 'chunk_pipe' ---
        // qk_full: 5 barriers, init_count=1
        mbarrier_init_r61(smem + 0, 1);
        mbarrier_init_r61(smem + 8, 1);
        mbarrier_init_r61(smem + 16, 1);
        mbarrier_init_r61(smem + 24, 1);
        mbarrier_init_r61(smem + 32, 1);
        // gate_raw_full: 5 barriers, init_count=1
        mbarrier_init_r61(smem + 40, 1);
        mbarrier_init_r61(smem + 48, 1);
        mbarrier_init_r61(smem + 56, 1);
        mbarrier_init_r61(smem + 64, 1);
        mbarrier_init_r61(smem + 72, 1);
#if defined(KDA_PREP_PIPE2)
        // qk_raw_full: 5 barriers, init_count=2 (k arrives from the previous
        // iteration's tail issue; q arrives from this iteration's top issue)
        mbarrier_init_r61(smem + 80, 2);
        mbarrier_init_r61(smem + 88, 2);
        mbarrier_init_r61(smem + 96, 2);
        mbarrier_init_r61(smem + 104, 2);
        mbarrier_init_r61(smem + 112, 2);
#else
        // qk_raw_full: 5 barriers, init_count=1
        mbarrier_init_r61(smem + 80, 1);
        mbarrier_init_r61(smem + 88, 1);
        mbarrier_init_r61(smem + 96, 1);
        mbarrier_init_r61(smem + 104, 1);
        mbarrier_init_r61(smem + 112, 1);
#endif
        // v_full: 5 barriers, init_count=1
        mbarrier_init_r61(smem + 120, 1);
        mbarrier_init_r61(smem + 128, 1);
        mbarrier_init_r61(smem + 136, 1);
        mbarrier_init_r61(smem + 144, 1);
        mbarrier_init_r61(smem + 152, 1);
        // v_free: 5 barriers, init_count=4
        mbarrier_init_r61(smem + 160, 4);
        mbarrier_init_r61(smem + 168, 4);
        mbarrier_init_r61(smem + 176, 4);
        mbarrier_init_r61(smem + 184, 4);
        mbarrier_init_r61(smem + 192, 4);
        // smem_free: 5 barriers, init_count=1
        mbarrier_init_r61(smem + 200, 1);
        mbarrier_init_r61(smem + 208, 1);
        mbarrier_init_r61(smem + 216, 1);
        mbarrier_init_r61(smem + 224, 1);
        mbarrier_init_r61(smem + 232, 1);
        // raw_inputs_free: 5 barriers, init_count=1
        mbarrier_init_r61(smem + 240, 1);
        mbarrier_init_r61(smem + 248, 1);
        mbarrier_init_r61(smem + 256, 1);
        mbarrier_init_r61(smem + 264, 1);
        mbarrier_init_r61(smem + 272, 1);
        // state_inp_ready: 5 barriers, init_count=4 (8 under KDA_STATE_COOP:
        // the 4 helper warps of the chunk-owning prep instance also arrive).
#if defined(KDA_STATE_COOP)
        mbarrier_init_r61(smem + 280, 8);
        mbarrier_init_r61(smem + 288, 8);
        mbarrier_init_r61(smem + 296, 8);
        mbarrier_init_r61(smem + 304, 8);
        mbarrier_init_r61(smem + 312, 8);
#else
        mbarrier_init_r61(smem + 280, 4);
        mbarrier_init_r61(smem + 288, 4);
        mbarrier_init_r61(smem + 296, 4);
        mbarrier_init_r61(smem + 304, 4);
        mbarrier_init_r61(smem + 312, 4);
#endif
        // old_out_ready: 5 barriers, init_count=1
        mbarrier_init_r61(smem + 320, 1);
        mbarrier_init_r61(smem + 328, 1);
        mbarrier_init_r61(smem + 336, 1);
        mbarrier_init_r61(smem + 344, 1);
        mbarrier_init_r61(smem + 352, 1);
        // u_inp_ready: 5 barriers, init_count=4
        mbarrier_init_r61(smem + 360, 4);
        mbarrier_init_r61(smem + 368, 4);
        mbarrier_init_r61(smem + 376, 4);
        mbarrier_init_r61(smem + 384, 4);
        mbarrier_init_r61(smem + 392, 4);
#if defined(KDA_UIHI)
        // u_inp_ready_hi: 5 barriers, init_count=4 (round-39 supervisor
        // experiment; the R37-03 u_inp_ready split fully wired this time).
        // The compute warps arrive here once per stage when the HIGH half of
        // the residual TMEM store (u_inp cols +8..16) retires, while the
        // ordinary u_inp_ready arrive moves up to the LOW-half store. The
        // MMA warp can then launch UMMA-3's first K-issue as soon as the low
        // half is done and only gate the second K-issue on this barrier,
        // overlapping the producer's half-1 math + store with K-issue 1.
        // Region 784..824 is free (rebuild_done 744..776, init_state 704,
        // gt_ready 664..696, tmem_addr 616).
        mbarrier_init_r61(smem + 784, 4);
        mbarrier_init_r61(smem + 792, 4);
        mbarrier_init_r61(smem + 800, 4);
        mbarrier_init_r61(smem + 808, 4);
        mbarrier_init_r61(smem + 816, 4);
#endif
        // u2_acc_ready: 5 barriers, init_count=1
        mbarrier_init_r61(smem + 400, 1);
        mbarrier_init_r61(smem + 408, 1);
        mbarrier_init_r61(smem + 416, 1);
        mbarrier_init_r61(smem + 424, 1);
        mbarrier_init_r61(smem + 432, 1);
#if defined(KDA_RES_FUSE) || defined(KDA_U2_PACK)
        // u2_inp_ready: 5 barriers, init_count=1 (KDA_RES_FUSE / KDA_U2_PACK:
        // MMA-warp UMMA-3 commit arrives directly; the compute-warp repack is
        // gone)
        mbarrier_init_r61(smem + 440, 1);
        mbarrier_init_r61(smem + 448, 1);
        mbarrier_init_r61(smem + 456, 1);
        mbarrier_init_r61(smem + 464, 1);
        mbarrier_init_r61(smem + 472, 1);
#else
        // u2_inp_ready: 5 barriers, init_count=4
        mbarrier_init_r61(smem + 440, 4);
        mbarrier_init_r61(smem + 448, 4);
        mbarrier_init_r61(smem + 456, 4);
        mbarrier_init_r61(smem + 464, 4);
        mbarrier_init_r61(smem + 472, 4);
#endif
        // final_ready: 5 barriers, init_count=1
        mbarrier_init_r61(smem + 480, 1);
        mbarrier_init_r61(smem + 488, 1);
        mbarrier_init_r61(smem + 496, 1);
        mbarrier_init_r61(smem + 504, 1);
        mbarrier_init_r61(smem + 512, 1);
        // out_empty: 1 barriers, init_count=1
        mbarrier_init_r61(smem + 520, 1);
        // tmem_dealloc_ready: 1 barriers, init_count=2
        mbarrier_init_r61(smem + 528, 2);
        // prep_diag_ready: 5 barriers, init_count=2
        mbarrier_init_r61(smem + 536, 2);
        mbarrier_init_r61(smem + 544, 2);
        mbarrier_init_r61(smem + 552, 2);
        mbarrier_init_r61(smem + 560, 2);
        mbarrier_init_r61(smem + 568, 2);
        // prep_inv16_ready: 5 barriers, init_count=2
        mbarrier_init_r61(smem + 576, 2);
        mbarrier_init_r61(smem + 584, 2);
        mbarrier_init_r61(smem + 592, 2);
        mbarrier_init_r61(smem + 600, 2);
        mbarrier_init_r61(smem + 608, 2);
#if defined(KDA_PREP_PIPE2)
        // beta_raw_full: 5 barriers, init_count=1 (de-aliased beta prefetch)
        mbarrier_init_r61(smem + 624, 1);
        mbarrier_init_r61(smem + 632, 1);
        mbarrier_init_r61(smem + 640, 1);
        mbarrier_init_r61(smem + 648, 1);
        mbarrier_init_r61(smem + 656, 1);
#endif
#if defined(KDA_STATE_HOIST)
        // gt_ready: 5 barriers, init_count=4 (one arrive per prep warp of the
        // owning instance). Prep publishes smem_gt_all fp32 gate values here
        // mid-body (much earlier than qk_full) so the hoisted compute-side
        // state scale can consume them one chunk early without racing prep.
        mbarrier_init_r61(smem + 664, 4);
        mbarrier_init_r61(smem + 672, 4);
        mbarrier_init_r61(smem + 680, 4);
        mbarrier_init_r61(smem + 688, 4);
        mbarrier_init_r61(smem + 696, 4);
#endif
#if defined(KDA_STATE_FUSE)
        // rebuild_done: 5 stage barriers, init_count=1 (see m64 FUSE notes).
        mbarrier_init_r61(smem + 744, 1);
        mbarrier_init_r61(smem + 752, 1);
        mbarrier_init_r61(smem + 760, 1);
        mbarrier_init_r61(smem + 768, 1);
        mbarrier_init_r61(smem + 776, 1);
#endif
#if defined(KDA_STATE_COOP)
        // init_state_ready: 1 barrier, init_count=4 (one elect-arrive per
        // compute warp after its initial-state TMEM stores complete; the
        // chunk-0 helper warps gate on it.
        mbarrier_init_r61(smem + 704, 4);
#endif
        asm volatile("fence.mbarrier_init.release.cluster;");
        #undef mbarrier_init_r61
    }

    __syncthreads();

    // TMEM alloc (256 columns, 256 used)
    volatile int* tmem_addr_storage = (volatile int*)(smem_raw + 616);
    if (warp == 0) {
        int _tmem_hold = smem + 616;
        asm volatile("tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], %1;" :: "r"(_tmem_hold), "r"(256) : "memory");
    }

    __syncthreads();
    asm volatile("tcgen05.fence::after_thread_sync;");

    const int mbar_base = smem;
    #define qk_full_addr (mbar_base + 0)
    #define gate_raw_full_addr (mbar_base + 40)
    #define qk_raw_full_addr (mbar_base + 80)
    #define v_full_addr (mbar_base + 120)
    #define v_free_addr (mbar_base + 160)
    #define smem_free_addr (mbar_base + 200)
    #define raw_inputs_free_addr (mbar_base + 240)
    #define state_inp_ready_addr (mbar_base + 280)
    #define old_out_ready_addr (mbar_base + 320)
    #define u_inp_ready_addr (mbar_base + 360)
    #define u_inp_ready_hi_addr (mbar_base + 784)
    #define u2_acc_ready_addr (mbar_base + 400)
    #define u2_inp_ready_addr (mbar_base + 440)
    #define final_ready_addr (mbar_base + 480)
    #define out_empty_addr (mbar_base + 520)
    #define tmem_dealloc_ready_addr (mbar_base + 528)
    #define prep_diag_ready_addr (mbar_base + 536)
    #define prep_inv16_ready_addr (mbar_base + 576)
    #define beta_raw_full_addr (mbar_base + 624)
    #define gt_ready_addr (mbar_base + 664)
    #define rebuild_done_addr (mbar_base + 744)
    #define init_state_ready_addr (mbar_base + 704)
#if defined(KDA_STATE_FUSE)
    // diag tiles for the fused state rebuild live in the dead v-stage region
    // (v consumed before the build; stage v-TMA reload gated on rebuild_done).
    const int smem_diag_addr = smem + 32384;
#endif
    const int taddr = tmem_addr_storage[0];

    // Kernel post-init ops
    const int tmem_tmem_state = taddr + 64;
    const int tmem_tmem_state_inp = taddr;
    const int tmem_tmem_u_acc = taddr + 224;
    const int tmem_tmem_u2_inp = taddr + 224;
    const int tmem_tmem_u2_acc = taddr;
    const int tmem_tmem_out = taddr + 192;
    const int tmem_tmem_state_out = taddr + 64;
#if defined(KDA_U2_PACK)
    // KDA_U2_PACK: u2's packed f16 home is the dead bf16 state_inp region
    // (cols 0..16). Safe: RAW vs UMMA-1/2 A reads is gated by the MMA warp's
    // raw_inputs_free wait; the next chunk's state pack republishes cols
    // 0..64 only after final_ready(i) committed UMMA-4's read of u2.
    const int tmem_u2_packed = taddr + 0;
#endif

    // ---- Register redistribution for WGs split across roles ----
    // Dec phase frees registers before any WG attempts inc.
    if (warp >= 8 && warp <= 11) {
        asm volatile("setmaxnreg.dec.sync.aligned.u32 48;");
    }

    // ---- Role: compute ----
    if (warp <= 3) {
        asm volatile("setmaxnreg.inc.sync.aligned.u32 168;");
        { // compute_main
            int task_idx = blockIdx.x;
            int seq_idx = seq_order[task_idx / num_heads];
            int head_idx = task_idx % num_heads;
            long long bos = cu_seqlens[seq_idx];
            long long eos = cu_seqlens[seq_idx + 1];
            int seq_len = (int)(eos - bos);
            KDA_SPLIT_WINDOW(bos, eos, seq_len)
            int num_chunks = (seq_len + 32 - 1) / 32;
            int warp_in_wg = warp % 4;
            const int tmem_row_base = warp_in_wg * 32 << 16;
            int state_row = warp_in_wg * 32 + lane;
            int warp_id_in_role = (warp - 0);
            int compute_local_warp = warp_id_in_role;
            long long state_base = (((long long)seq_idx * (long long)num_heads + (long long)head_idx) * 128 + (long long)state_row) * 128;
            if (fixup_mode != 0) {
                // The initial_state input is the scan's carry buffer laid out
                // [part-1][(seq, head)][128*128]; part_y selects the part.
                state_base += (long long)(part_y) * (long long)num_bids * 16384;
            }
            if (fixup_mode == 3) {
                // Fused scan/correction (round 48): wait until all 32
                // scan-band CTAs of (task, split_part) have published this
                // part's carry. Only the compute warps spin here; the TMA
                // producer/consumer warps run their full-chunk prologue
                // concurrently, hiding the scan tail behind input prefetch.
                // One leader thread polls (thousands of acquire-loads on the
                // same L2 line from every compute thread measurably starve
                // the scan CTAs' M-staging traffic); the named barrier then
                // releases all four compute warps together.
                if (tid == 0) {
                    const int* _fp = progress_flags + (long long)task_idx * (long long)split_num_parts + (long long)split_part;
                    int _fv;
                    do {
                        asm volatile("ld.acquire.gpu.global.b32 %0, [%1];" : "=r"(_fv) : "l"(_fp) : "memory");
                        if (_fv < 32) __nanosleep(256);
                    } while (_fv < 32);
                }
                asm volatile("barrier.sync 7, 128;" ::: "memory");
            }
#if defined(KDA_TMA0_FIRST)
            // Round-63 supervisor directive: issue ALL chunk-0 input TMAs
            // (gate/beta/k for pipeline waves 0 and 2, the first wave's q,
            // and chunk-0's v) BEFORE the initial-state LDG/TMEM stream so
            // the transfers overlap the measured ~6us long-scoreboard startup
            // ramp instead of waiting for the R62 prefetch to recall the LDG
            // lines. The default issue path waits for the R62 LI/LDG recall
            // AND for the epilogue prologue's syncthreads-window, so the raw
            // input stream effectively starts two barrier phases later than
            // the initial-state stream. Here the compute warps' leader lane
            // (tid==path-branch-exact single-lane issue, no elect needed)
            // launches them unconditionally at kernel entry: every predecessor
            // barrier (raw_inputs_free[0..4], smem_free[0..4], v_free[0..4])
            // is fresh and immediately free, the destination stage windows
            // are untouched, and the TMA hardware itself tolerates the
            // buffer-bys arrival because the consumers wait parity 0.
            //
            // Coverage and predication deliberately mirror the default path:
            // both waves' g/beta/k are independent of pos, which is only
            // consumed inside tmp_full's produce. The q TMA is first-instance
            // only (the R60 slab path always runs the q-pipeline through the
            // single prep instance; mirroring KDA_PREP_PIPE2's all-instance
            // prefetch would double the qk_raw barrier arrival count). v's
            // issue is de-gated from the epilogue-only qk_full dependency
            // (v is not produced from q/k data until UMMA-2's FMA retire)
            // via a pre-wait arrive_expect_tx on v_full[0], preserving the
            // barrier's transaction-count arithmetic bit-for-bit.
            if (compute_local_warp == 0) {
                if (elect_sync()) {
                    #pragma unroll
                    for (int _t0w = 0; _t0w < 2; _t0w++) {
                        // prep_stage == prep_instance for each instance's
                        // first chunk (chunk == instance on iter 0), so the
                        // stage index of chunk c is c itself for c < 5:
                        // chunk 0 -> stage 0, chunk 4 -> stage 4.
                        int _t0stage = _t0w * 4;
                        int _t0chunk = _t0w * 4;
                        if (seq_len >= (_t0chunk + 1) * 32) {
