                    if (elect_sync()) {
                        mbarrier_arrive_expect_tx(gate_raw_full_addr + (prep_stage) * 8, 8704);
                        tma_3d_gmem2smem(smem_g_raw_addr + prep_stage * KDA_STAGE_BYTES, g_tma, 0, head_idx_3, (int)(bos_4 + (long long)(prep_instance * 32)), gate_raw_full_addr + (prep_stage) * 8);
                        tma_2d_gmem2smem(smem_beta_raw_addr + prep_stage * KDA_STAGE_BYTES, beta_tma, head_idx_3 / 8 * 8, (int)(bos_4 + (long long)(prep_instance * 32)), gate_raw_full_addr + (prep_stage) * 8);
                        mbarrier_arrive_expect_tx(qk_raw_full_addr + (prep_stage) * 8, 8192);
                        tma_4d_gmem2smem(smem_kd_addr + prep_stage * KDA_STAGE_BYTES, k_tma, 0, (int)(bos_4 + (long long)(prep_instance * 32)), head_idx_3, 0, qk_raw_full_addr + (prep_stage) * 8);
                    }
                }
            }
#elif defined(KDA_PREP_PIPE)
            // Software-pipelined prep (supervisor R6): issue this instance's
            // first full chunk's gate/beta TMA up front (the raw_inputs_free
            // wait is the initial "free" state). Inside the loop, the NEXT
            // full chunk's gate/beta TMA is issued at the very end of the
            // body — as soon as this stage's next raw_inputs_free phase can
            // be awaited — instead of at the next iteration top, so the
            // transfer overlaps the loop tail and downstream role work.
            // NOTE: g_raw/beta_raw alias the qd output and restore_factor
            // regions of this stage window, so the launch must NOT move
            // earlier than the end of the body (prep reads qd/restore data
            // from the same bytes until the loop tail).
            if (prep_instance < num_chunks_4 && seq_len_4 >= (prep_instance + 1) * 32) {
                mbarrier_wait(raw_inputs_free_addr + (prep_stage) * 8, _phase_raw_inputs_free);
                _phase_raw_inputs_free ^= 1;
                if (prep_local_warp == 0) {
                    if (elect_sync()) {
                        mbarrier_arrive_expect_tx(gate_raw_full_addr + (prep_stage) * 8, 8704);
                        tma_3d_gmem2smem(smem_g_raw_addr + prep_stage * KDA_STAGE_BYTES, g_tma, 0, head_idx_3, (int)(bos_4 + (long long)(prep_instance * 32)), gate_raw_full_addr + (prep_stage) * 8);
                        tma_2d_gmem2smem(smem_beta_raw_addr + prep_stage * KDA_STAGE_BYTES, beta_tma, head_idx_3 / 8 * 8, (int)(bos_4 + (long long)(prep_instance * 32)), gate_raw_full_addr + (prep_stage) * 8);
                    }
                }
            }
#endif
            #pragma unroll 1
            for (int prep_iter = 0; prep_iter < num_prep_iters; prep_iter++) {
                int chunk_idx_3 = prep_iter * KDA_NUM_PREP_INSTANCES + prep_instance;
                int stage_f32 = prep_stage * KDA_STAGE_F32;
                int stage_bf16 = prep_stage * KDA_STAGE_ELEMS;
                int chunk_is_full_2 = ((seq_len_4 >= (chunk_idx_3 + 1) * 32) ? 1 : 0);
                float early_beta_value = 0.0f;
                float early_gate0 = 0.0f;
                if (chunk_is_full_2 != 0) {
#if defined(KDA_GPREP)
                    // Round-75 GPREP: raw q/k/g/beta TMAs and the gate/beta
                    // early extraction are gone. The preprocessed qd1/kd1/ki
                    // tiles target the same stage windows (smem_qd/smem_kd/
                    // smem_ki), so the raw_inputs_free reservation protocol is
                    // unchanged; the gate_raw_full/qk_raw_full barriers are
                    // prep-internal and unused in this build.
                    mbarrier_wait(raw_inputs_free_addr + (prep_stage) * 8, _phase_raw_inputs_free);
#else
#if defined(KDA_PREP_PIPE2)
                    // gate/beta/k were all issued from the prologue or the
                    // previous iteration (beta mid-body, gate/k at the tail);
                    // only the raw-input barrier waits remain here.
                    mbarrier_wait(gate_raw_full_addr + (prep_stage) * 8, _phase_gate_raw_full);
                    _phase_gate_raw_full ^= 1;
#elif defined(KDA_PREP_PIPE)
                    // gate/beta (and the raw_inputs_free wait) were issued at
                    // the end of the previous iteration's body (or the
                    // prologue). Only the k TMA remains here.
                    if (prep_local_warp == 0) {
                        if (elect_sync()) {
                            mbarrier_arrive_expect_tx(qk_raw_full_addr + (prep_stage) * 8, 16384);
                            tma_4d_gmem2smem(smem_kd_addr + prep_stage * KDA_STAGE_BYTES, k_tma, 0, (int)(bos_4 + (long long)(chunk_idx_3 * 32)), head_idx_3, 0, qk_raw_full_addr + (prep_stage) * 8);
                        }
                    }
                    mbarrier_wait(gate_raw_full_addr + (prep_stage) * 8, _phase_gate_raw_full);
                    _phase_gate_raw_full ^= 1;
#else
#if defined(KDA_TMA0_FIRST)
                    // Round-63 supervisor directive: the compute-warp prologue
                    // issued ALL chunk-0 input TMAs unconditionally at kernel
                    // entry (before the initial-state LDG stream), so the
                    // raw_inputs_free wait still runs (preserves the pipeline
                    // protocol's phase arithmetic) but the g/beta/k TMAs
                    // for waves 0 and 2 (chunks 0 and 4) are suppressed.
                    mbarrier_wait(raw_inputs_free_addr + (prep_stage) * 8, _phase_raw_inputs_free);
                    bool issue_now = !(chunk_is_full_2 != 0 && (chunk_idx_3 == 0 || chunk_idx_3 == 4));
                    if (issue_now && prep_local_warp == 0) {
                        if (elect_sync()) {
                            mbarrier_arrive_expect_tx(gate_raw_full_addr + (prep_stage) * 8, 8704);
                            tma_3d_gmem2smem(smem_g_raw_addr + prep_stage * KDA_STAGE_BYTES, g_tma, 0, head_idx_3, (int)(bos_4 + (long long)(chunk_idx_3 * 32)), gate_raw_full_addr + (prep_stage) * 8);
                            tma_2d_gmem2smem(smem_beta_raw_addr + prep_stage * KDA_STAGE_BYTES, beta_tma, head_idx_3 / 8 * 8, (int)(bos_4 + (long long)(chunk_idx_3 * 32)), gate_raw_full_addr + (prep_stage) * 8);
                            // Map-only: no q TMA rides this barrier (skipped
                            // below), so qk_raw_full expects only k's bytes.
                            mbarrier_arrive_expect_tx(qk_raw_full_addr + (prep_stage) * 8, 16384);
                            tma_4d_gmem2smem(smem_kd_addr + prep_stage * KDA_STAGE_BYTES, k_tma, 0, (int)(bos_4 + (long long)(chunk_idx_3 * 32)), head_idx_3, 0, qk_raw_full_addr + (prep_stage) * 8);
                        }
                    }
                    mbarrier_wait(gate_raw_full_addr + (prep_stage) * 8, _phase_gate_raw_full);
#elif defined(KDA_MMA_ISSUE)
                    // Chunks >= 5: the MMA warp issued this chunk's
                    // gate/beta/k TMAs when it released raw_inputs_free for
                    // this stage; skip prep's own wait+issue. The first chunk
                    // of each instance (chunks 0..4) still uses prep-issued
                    // TMAs since no prior MMA commit exists.
                    if (chunk_idx_3 == prep_instance) {
                    mbarrier_wait(raw_inputs_free_addr + (prep_stage) * 8, _phase_raw_inputs_free);
                    if (prep_local_warp == 0) {
                        if (elect_sync()) {
                            mbarrier_arrive_expect_tx(gate_raw_full_addr + (prep_stage) * 8, 8704);
                            tma_3d_gmem2smem(smem_g_raw_addr + prep_stage * KDA_STAGE_BYTES, g_tma, 0, head_idx_3, (int)(bos_4 + (long long)(chunk_idx_3 * 32)), gate_raw_full_addr + (prep_stage) * 8);
                            tma_2d_gmem2smem(smem_beta_raw_addr + prep_stage * KDA_STAGE_BYTES, beta_tma, head_idx_3 / 8 * 8, (int)(bos_4 + (long long)(chunk_idx_3 * 32)), gate_raw_full_addr + (prep_stage) * 8);
                            // Map-only: no q TMA rides this barrier (skipped
                            // below), so qk_raw_full expects only k's bytes.
                            mbarrier_arrive_expect_tx(qk_raw_full_addr + (prep_stage) * 8, map_only_2 ? 8192 : 16384);
                            tma_4d_gmem2smem(smem_kd_addr + prep_stage * KDA_STAGE_BYTES, k_tma, 0, (int)(bos_4 + (long long)(chunk_idx_3 * 32)), head_idx_3, 0, qk_raw_full_addr + (prep_stage) * 8);
                        }
                    }
                    }
                    mbarrier_wait(gate_raw_full_addr + (prep_stage) * 8, _phase_gate_raw_full);
#else
                    mbarrier_wait(raw_inputs_free_addr + (prep_stage) * 8, _phase_raw_inputs_free);
                    if (prep_local_warp == 0) {
                        if (elect_sync()) {
                            mbarrier_arrive_expect_tx(gate_raw_full_addr + (prep_stage) * 8, 8704);
                            tma_3d_gmem2smem(smem_g_raw_addr + prep_stage * KDA_STAGE_BYTES, g_tma, 0, head_idx_3, (int)(bos_4 + (long long)(chunk_idx_3 * 32)), gate_raw_full_addr + (prep_stage) * 8);
                            tma_2d_gmem2smem(smem_beta_raw_addr + prep_stage * KDA_STAGE_BYTES, beta_tma, head_idx_3 / 8 * 8, (int)(bos_4 + (long long)(chunk_idx_3 * 32)), gate_raw_full_addr + (prep_stage) * 8);
                            // Map-only: no q TMA rides this barrier (skipped
                            // below), so qk_raw_full expects only k's bytes.
                            mbarrier_arrive_expect_tx(qk_raw_full_addr + (prep_stage) * 8, 16384);
                            tma_4d_gmem2smem(smem_kd_addr + prep_stage * KDA_STAGE_BYTES, k_tma, 0, (int)(bos_4 + (long long)(chunk_idx_3 * 32)), head_idx_3, 0, qk_raw_full_addr + (prep_stage) * 8);
                        }
                    }
                    mbarrier_wait(gate_raw_full_addr + (prep_stage) * 8, _phase_gate_raw_full);
#endif
#endif
                    if (prep_local_warp == 2 && lane < 32) {
                        unsigned int beta_raw_pair[1];
                        asm volatile("ld.shared.b32 %0, [%1];" : "=r"(*reinterpret_cast<uint32_t*>(&beta_raw_pair[0])) : "r"(smem_beta_raw_addr + prep_stage * KDA_STAGE_BYTES + (unsigned int)(lane * 16) + (unsigned int)(head_idx_3 % 8 / 2 * 4)));
                        float beta_raw_pair_fp32[2];
                        #pragma unroll
                        for (int _pair = 0; _pair < 1; _pair++) {
                            asm volatile(
                                "{\n\t"
                                "shl.b32 %0, %2, 16;\n\t"
                                "and.b32 %1, %2, 0xffff0000;\n\t"
                                "}\n"
                                : "=f"((&beta_raw_pair_fp32[_pair * 2])[0]), "=f"((&beta_raw_pair_fp32[_pair * 2])[1])
                                : "r"(beta_raw_pair[_pair + 0]));
                        }
                        float beta_logit = beta_raw_pair_fp32[0];
                        if (head_idx_3 % 2 != 0) {
                            beta_logit = beta_raw_pair_fp32[1];
                        }
                        float _tanh_approx_0;
                        asm volatile("tanh.approx.f32 %0, %1;" : "=f"(_tanh_approx_0) : "f"(beta_logit * 0.5f));
                        early_beta_value = _tanh_approx_0 * 0.5f + 0.5f;
                    }
#if !defined(KDA_F32X2)
                    if (prep_tid < 128) {
                        float early_gate_rate = smem_gate_rate_all[stage_f32];
#if defined(KDA_DTB_HOIST)
                        float early_gate_bias = dtb_reg;
#else
                        float early_gate_bias = dt_bias[head_idx_3 * 128 + prep_tid];
#endif
                        __nv_bfloat16 early_gate_raw = smem_g_raw_all[stage_bf16 + prep_tid];
                        float _cvt_f32_0 = __bfloat162float(early_gate_raw);
                        float early_gate_arg = early_gate_rate * (_cvt_f32_0 + early_gate_bias);
                        float _tanh_approx_1;
                        asm volatile("tanh.approx.f32 %0, %1;" : "=f"(_tanh_approx_1) : "f"(early_gate_arg * 0.5f));
                        float early_gate_sigmoid = _tanh_approx_1 * 0.5f + 0.5f;
                        early_gate0 = lower_bound * 1.4426950408889634f * early_gate_sigmoid;
                    }
#endif
#endif  // KDA_GPREP (raw TMA + early extraction)
                }
                mbarrier_wait(smem_free_addr + (prep_stage) * 8, _phase_smem_free);
#if !defined(KDA_GPREP)
#if defined(KDA_TMA0_FIRST)
                if (chunk_is_full_2 != 0 && !map_only_2 && chunk_idx_3 != 0) {
#else
                if (chunk_is_full_2 != 0 && !map_only_2) {
#endif
                    if (prep_local_warp == 0) {
                        if (elect_sync()) {
#if defined(KDA_PREP_PIPE2)
                            // q carries the second qk_raw_full arrival (k's
                            // came from the prologue / previous tail issue).
                            mbarrier_arrive_expect_tx(qk_raw_full_addr + (prep_stage) * 8, 8192);
#endif
                            tma_4d_gmem2smem(smem_q_raw_prefetch_addr + prep_stage * KDA_STAGE_BYTES, q_tma, 0, (int)(bos_4 + (long long)(chunk_idx_3 * 32)), head_idx_3, 0, qk_raw_full_addr + (prep_stage) * 8);
                        }
                    }
                }
#endif  // !KDA_GPREP (q raw TMA)
#if !defined(KDA_GPREP)
                if (chunk_is_full_2 == 0) {
                    #pragma unroll
                    for (int gate_load_pass = 0; gate_load_pass < 4; gate_load_pass++) {
                        int gate_load_item = gate_load_pass * 128 + prep_tid;
                        int gate_load_row = gate_load_item / 16;
                        int gate_load_segment = gate_load_item % 16;
                        long long gate_load_token = bos_4 + (long long)(chunk_idx_3 * 32 + gate_load_row);
                        long long gate_load_base = (gate_load_token * (long long)num_heads + (long long)head_idx_3) * 128 + (long long)(gate_load_segment * 8);
                        asm volatile("cp.async.cg.shared::cta.global [%0], [%1], 16, %2;"
                            :: "r"(smem_g_raw_addr + prep_stage * KDA_STAGE_BYTES + (unsigned int)(gate_load_item * 16)), "l"(g + gate_load_base), "r"((gate_load_token < eos_4) ? 16 : 0));
                    }
                }
#endif  // !KDA_GPREP (tail-chunk gate cp.async)
#if !defined(KDA_GPREP)
                if (chunk_is_full_2 == 0) {
                    asm volatile("cp.async.commit_group;");
                    asm volatile("cp.async.wait_group 0;");
                    if (prep_instance == 0) {
                        asm volatile("barrier.sync 11, 128;" ::: "memory");
                    } else if (prep_instance == 1) {
                        asm volatile("barrier.sync 12, 128;" ::: "memory");
                    } else {
                        if (prep_instance == 2) {
                            asm volatile("barrier.sync 13, 128;" ::: "memory");
                        } else if (prep_instance == 3) {
                            asm volatile("barrier.sync 14, 128;" ::: "memory");
                        } else {
                            asm volatile("barrier.sync 15, 128;" ::: "memory");
                        }
                    }
                }
                if (prep_local_warp == 2 && lane < 32) {
                    float beta_value = early_beta_value;
                    if (chunk_is_full_2 == 0) {
                        long long beta_token = bos_4 + (long long)(chunk_idx_3 * 32 + lane);
                        if (beta_token < eos_4) {
                            float beta_logit_1 = (float)beta[beta_token * (long long)num_heads + (long long)head_idx_3];
                            float _tanh_approx_2;
                            asm volatile("tanh.approx.f32 %0, %1;" : "=f"(_tanh_approx_2) : "f"(beta_logit_1 * 0.5f));
                            beta_value = _tanh_approx_2 * 0.5f + 0.5f;
                        }
                    }
                    smem_prep_beta_all[stage_f32 + lane] = beta_value;
                }
#else
                // Round-75 GPREP: bsig = sigmoid(beta) is precomputed in the
                // producer buffer [T,H] fp32; invalid tail lanes mirror the
                // default path's 0.5 (sigmoid of the TMA zero fill).
                if (prep_local_warp == 2 && lane < 32) {
                    long long beta_token = bos_4 + (long long)(chunk_idx_3 * 32 + lane);
                    float beta_value = 0.5f;
                    if (beta_token < eos_4) {
                        beta_value = gp_bsig[beta_token * (long long)num_heads + (long long)head_idx_3];
                    }
                    smem_prep_beta_all[stage_f32 + lane] = beta_value;
                }
#endif  // KDA_GPREP (beta publish)
#if defined(KDA_GPREP)
                // Round-75 GPREP: gt = 2^(total gate_log2) is precomputed per
                // (physical chunk, head) fp32[128]; publish it directly into
                // the smem_gt_all window (readers: compute-warp state scale,
                // and this instance's slim restore via gt * gp_ic). No gate
                // scan, no smem_gate_all / smem_gt_prefix_all traffic.
                const int gprep_chunk_gid = gp_seq_chunk_base[seq_idx_4]
                    + (int)((bos_4 - gprep_orig_bos_4) / 32) + chunk_idx_3;
                if (prep_tid < 128) {
                    smem_gt_all[stage_f32 + prep_tid] =
                        gp_gt[((long long)gprep_chunk_gid * (long long)num_heads + (long long)head_idx_3) * 128 + prep_tid];
                }
#else
#if !defined(KDA_GATE_SHFL)
                if (prep_tid < 128) {
                    int gate_col = prep_tid;
#if defined(KDA_GATE_PERM)
                    // Round-13: permuted gate layout so the prep
                    // reader's merged LDS.128s cover consecutive
                    // 16B blocks (conflict-free).
                    const int gate_col_p = ((gate_col >> 3) << 2) + (gate_col & 3) + ((gate_col & 4) << 4);
#elif defined(KDA_GATE_SWIZZLE)
                    // Round-66: 16B-group swizzled gate layout (see
                    // gate_swz_grp). Writer scalar stores stay
                    // conflict-free; reader LDS.128s stay conflict-free.
                    const int gate_col_p = gate_swz_col(gate_col);
#else
                    const int gate_col_p = gate_col;
#endif
                    float gate_rate = smem_gate_rate_all[stage_f32];
#if defined(KDA_DTB_HOIST)
                    float gate_bias = dtb_reg;
#else
                    float gate_bias = dt_bias[head_idx_3 * 128 + gate_col];
#endif
                    float prefix_log2 = 0.0f;
#if defined(KDA_F32X2)
                    if (chunk_is_full_2 != 0) {
                        // Packed row-pair gate scan: one fma.f32x2 computes
                        // arg = (0.5*rate)*g + 0.5*rate*bias for two rows and
                        // one fma.f32x2 computes gate_log2 = 0.5*k_log*tanh +
                        // 0.5*k_log; only the two prefix adds stay serial.
                        const float k_log_r2 = lower_bound * 1.4426950408889634f;
                        const float2 hk_log2v = {0.5f * k_log_r2, 0.5f * k_log_r2};
                        const float2 c0_r2 = {0.5f * gate_rate, 0.5f * gate_rate};
                        const float c1_r2s = 0.5f * gate_rate * gate_bias;
                        const float2 c1_r2 = {c1_r2s, c1_r2s};
#if defined(KDA_PREP_NULL)
                        // R74 ceiling probe (correctness-INVALID): publish a
                        // zero gate prefix; the tanh/fma scan math is skipped.
                        // Barrier/publish structure is unchanged.
                        #pragma unroll
                        for (int gate_row = 0; gate_row < 32; gate_row++) {
                            smem_gate_all[stage_f32 + gate_row * 128 + gate_col_p] = 0.0f;
                        }
                        prefix_log2 = 0.0f;
#else
                        #pragma unroll
                        for (int gate_row = 0; gate_row < 32; gate_row += 2) {
                            float2 g2;
                            g2.x = __bfloat162float(smem_g_raw_all[stage_bf16 + gate_row * 128 + gate_col]);
                            g2.y = __bfloat162float(smem_g_raw_all[stage_bf16 + (gate_row + 1) * 128 + gate_col]);
                            float2 arg2 = g2;
                            fma_f32x2_inplace(&arg2, c0_r2, c1_r2);
                            float2 t2;
                            asm volatile("tanh.approx.f32 %0, %1;" : "=f"(t2.x) : "f"(arg2.x));
                            asm volatile("tanh.approx.f32 %0, %1;" : "=f"(t2.y) : "f"(arg2.y));
                            float2 gl2 = t2;
                            fma_f32x2_inplace(&gl2, hk_log2v, hk_log2v);
                            prefix_log2 += gl2.x;
                            smem_gate_all[stage_f32 + gate_row * 128 + gate_col_p] = prefix_log2;
                            prefix_log2 += gl2.y;
                            smem_gate_all[stage_f32 + (gate_row + 1) * 128 + gate_col_p] = prefix_log2;
                        }
#endif  // KDA_PREP_NULL
                    } else
#endif
                    for (int gate_row = 0; gate_row < 32; gate_row++) {
                        long long gate_token = bos_4 + (long long)(chunk_idx_3 * 32 + gate_row);
                        float gate_log2 = 0.0f;
                        int gate_needs_compute = 1;
                        if (gate_row == 0) {
                            if (chunk_is_full_2 != 0) {
                                gate_log2 = early_gate0;
                                gate_needs_compute = 0;
                            }
                        }
                        if (gate_needs_compute != 0) {
                            if (gate_token < eos_4) {
                                __nv_bfloat16 gate_raw = smem_g_raw_all[stage_bf16 + gate_row * 128 + gate_col];
                                float _cvt_f32_1 = __bfloat162float(gate_raw);
                                float gate_arg = gate_rate * (_cvt_f32_1 + gate_bias);
                                float _tanh_approx_3;
                                asm volatile("tanh.approx.f32 %0, %1;" : "=f"(_tanh_approx_3) : "f"(gate_arg * 0.5f));
                                float gate_sigmoid = _tanh_approx_3 * 0.5f + 0.5f;
                                gate_log2 = lower_bound * 1.4426950408889634f * gate_sigmoid;
                            }
                        }
                        prefix_log2 += gate_log2;
                        smem_gate_all[stage_f32 + gate_row * 128 + gate_col_p] = prefix_log2;
                    }
                }
#endif  // !KDA_GATE_SHFL (standalone column scan -> smem_gate_all)
                if (prep_instance == 0) {
                    asm volatile("barrier.sync 11, 128;" ::: "memory");
                } else if (prep_instance == 1) {
                    asm volatile("barrier.sync 12, 128;" ::: "memory");
                } else {
                    if (prep_instance == 2) {
                        asm volatile("barrier.sync 13, 128;" ::: "memory");
                    } else if (prep_instance == 3) {
                        asm volatile("barrier.sync 14, 128;" ::: "memory");
                    } else {
                        asm volatile("barrier.sync 15, 128;" ::: "memory");
                    }
                }
                if (chunk_is_full_2 != 0) {
                    mbarrier_wait(qk_raw_full_addr + (prep_stage) * 8, _phase_qk_raw_full);
                }
#if !defined(KDA_GATE_SHFL)
                if (prep_tid < 128) {
#if defined(KDA_GATE_PERM)
                    const int gt_col_r = ((prep_tid >> 3) << 2) + (prep_tid & 3) + ((prep_tid & 4) << 4);
#else
                    const int gt_col_r = prep_tid;
#endif
                    float total_log2 = smem_gt_prefix_all[stage_f32 + gt_col_r];
                    float _exp2_0 = approx_exp2(total_log2 - lower_bound * 1.4426950408889634f * 16.0f);
#if defined(KDA_PREP_PIPE2)
                    smem_restore2_all[prep_stage * 160 + prep_tid] = _exp2_0;
#else
                    smem_restore_factor_all[stage_f32 + prep_tid] = _exp2_0;
#endif
                }
                if (prep_tid == 0) {
                    float _exp2_1 = approx_exp2(lower_bound * 1.4426950408889634f * 16.0f);
#if defined(KDA_PREP_PIPE2)
                    smem_restore2_all[prep_stage * 160 + 128] = _exp2_1;
#else
                    smem_restore_factor_all[stage_f32 + 128] = _exp2_1;
#endif
                }
#endif  // !KDA_GATE_SHFL (early restore-factor publish)
#endif  // KDA_GPREP (gate scan + restore-factor publish)
#if defined(KDA_GPREP)
