                    // the fp32 state only after chunk c-1's MMA-4 state
                    // accumulate retired (final_ready[(c-1)%5]) and, for
                    // c == 0, after the compute warps' initial-state TMEM
                    // store. One completion and one wait per 5 chunks per
                    // stage, skew <= 1 phase (helpers cannot run ahead: MMA
                    // progress past i-1 requires this very arrival).
                    int coop_c = prep_iter * KDA_NUM_PREP_INSTANCES + prep_instance;
                    if (coop_c == 0) {
                        mbarrier_wait(init_state_ready_addr, 0u);
                    } else {
                        int coop_gstage = (prep_instance == 0) ? 4 : (prep_instance - 1);
                        mbarrier_wait(final_ready_addr + coop_gstage * 8, _phase_coop_fin);
                        _phase_coop_fin ^= 1;
                    }
                    const int coop_row_base = (warp % 4) * 32 << 16;
                    const int coop_gt_base = prep_stage * KDA_STAGE_F32;
                    #pragma unroll 1
                    for (int coop_blk = 2; coop_blk < 4; coop_blk++) {
                        #pragma unroll
                        for (int coop_half = 0; coop_half < 2; coop_half++) {
                            float coop_state[16];
                            tmem_ld_x16(&coop_state[0], taddr + 64 + (unsigned int)coop_row_base + (unsigned int)(coop_blk * 32) + (unsigned int)(coop_half * 16));
                            uint32_t coop_bf16[8];
                            #pragma unroll
                            for (int _lp = 0; _lp < 8; _lp++) {
                                __nv_bfloat162 _bf2 = __float22bfloat162_rn(make_float2(coop_state[_lp*2 + 0], coop_state[_lp*2+1 + 0]));
                                coop_bf16[_lp] = *(uint32_t*)&_bf2;
                            }
                            tmem_st_x8_u32(taddr + (unsigned int)coop_row_base + (unsigned int)(coop_blk * 16) + (unsigned int)(coop_half * 8), (const uint32_t*)coop_bf16);
                            float coop_scale[16];
                            #pragma unroll
                            for (int coop_col = 0; coop_col < 16; coop_col++) {
                                coop_scale[coop_col] = smem_gt_all[coop_gt_base + (unsigned int)(coop_blk * 32) + (unsigned int)(coop_half * 16) + (unsigned int)coop_col];
                            }
                            #pragma unroll
                            for (int _ls = 0; _ls < 8; _ls++)
                                mul_f32x2_inplace(&reinterpret_cast<float2*>(coop_state)[_ls], reinterpret_cast<const float2*>(coop_scale)[_ls]);
                            int coop_state_addr = taddr + 64 + (unsigned int)coop_row_base + (unsigned int)(coop_blk * 32) + (unsigned int)(coop_half * 16);
                            tmem_st_x8_u32(coop_state_addr, (const uint32_t*)coop_state);
                            tmem_st_x8_u32(coop_state_addr + 8, (const uint32_t*)(coop_state + 8));
                        }
                    }
                }
                asm volatile("tcgen05.wait::st.sync.aligned;" ::: "memory");
                if (elect_sync()) {
                    mbarrier_arrive(state_inp_ready_addr + (prep_stage) * 8);
                }
#endif
                for (int _advance = 0; _advance < NUM_CHUNK_PIPE_STAGES; _advance++) {
                    prep_stage += 1;
                    if (prep_stage == NUM_CHUNK_PIPE_STAGES) { prep_stage = 0;
#if !defined(KDA_PREP_PIPE) && !defined(KDA_PREP_PIPE2)
                        _phase_raw_inputs_free ^= 1; _phase_gate_raw_full ^= 1;
#endif
                        _phase_smem_free ^= 1; _phase_qk_raw_full ^= 1; _phase_prep_diag_ready ^= 1; _phase_prep_inv16_ready ^= 1; }
                }
            }
        }
    }

    // Cleanup
}

// Split-seq dense scan: compose the per-part affine transforms exported by the
// main and map passes into per-part prefix (carry) states:
//   c_1 = part-0 end state from the main pass (initial state absorbed),
//   c_{p+1} = S_p + M_p x c_p  (p >= 1)
// where S_p is the part's zero-init end state (split_state), M_p is the part's
// exact linear operator on the incoming state (map_state, exported from the
// V:=0 identity-init map pass: c'[v,k] = sum_k' c[v,k'] * M[k',k]), and the
// emitted carry[p-1] is c_p in fp32, consumed by the correction pass as its
// initial state. Layouts: split_state/map_state [(task*P + p)][128*128] fp32,
// carry [part-1][(seq_idx*H + head)][128*128] fp32 (part stride = tasks*16384).
// Grid: (tasks, 8); each CTA owns a 16-row band of the state. 256 threads =
// 16 v-rows x 16 k-groups; thread (vl, kg) owns columns kg + i*16 (i < 8),
// which keeps the M smem reads bank-conflict-free (consecutive-word groups).
// M is staged in dynamic SMEM (padded rows) once per step; c ping-pongs
// between two padded 16-row SMEM buffers.
// Round-50 A/B matrix: ROWS picks the R45 v2 default (ROWS=4, grid.y=32
// bands) or the 64 two-row schedule (ROWS=2, grid.y=64 — measured neutral at
// H1 and regressive at H4/H8; debug switch only). BULK selects the round-50
// v3 staging: the 64KB M_p panel is copied global->shared with ONE
// cp.async.bulk tracked on an mbarrier instead of 4096 per-thread LDG.128 +
// STS.128 pairs, because NCU warp-stall sampling (r50_scan.ncu-rep at
// 131072xH1) pinned the staging STS.128 scoreboard waits as the dominant
// per-pass stall. BULK drops the M panel padding (MPAD 132 -> 128: float4
// phases stay bank-conflict-free with a 128-float pitch) so one contiguous
// 64KB copy per panel suffices. Math and fp32 accumulation order are
// identical in all variants.
} // extern "C" (reopened after the templated scan kernel)
template <int ROWS, int BULK>
__global__ __launch_bounds__(256) void kernel_flashkda_split_scan_m128(
    const __nv_bfloat16* __restrict__ initial_state,
    const float* __restrict__ split_state,
    const float* __restrict__ map_state,
    float* __restrict__ carry,
    const int* __restrict__ seq_order,
    int num_heads, int split_num_parts, int use_initial_state)
{
    // Round-45 latency fix (torch.profiler on the four split shapes: scan is
    // 635us of 880us at 131072xH1 and 754us of 2075us at 1048576xH1, ~5us per
    // serial pass; per-pass cost is the 64KB global->smem M_p staging, issued
    // only AFTER the previous pass's syncthreads):
    // (a) grid.y covers 32 row-bands of 4 state rows each (32 CTAs per task,
    // halving each CTA's matvec issue time: only ROWS warps issue the smem
    // matvec now, the others stage/sync),
    // (b) M_{p+1} is prefetched into a DOUBLE-BUFFERED smem panel BEFORE this
    // pass's matvec so the 16xfloat4 global loads per thread overlap the
    // compute (~2x fewer exposed stalls; pass p-1's reads of that buffer
    // retired at the end-of-pass syncthreads),
    // (c) the c_p emit and S_{p+1} register prefetch keep their R33 placement.
    // Math and per-element fp32 accumulation order are unchanged from R33.
    extern __shared__ __align__(1024) float scan_smem[];
    // BULK needs contiguous 64KB panels for the single cp.async.bulk; with a
    // 128-float pitch every float4 phase still covers all 32 banks exactly
    // once (row base kp*512B is 128B-aligned, lanes cover words 0..127), so
    // the +4 padding carried no value once accesses became float4-only.
    constexpr int MPAD = BULK ? 128 : 132;
    // Round-49 alignment fix: CPAD must be a multiple of 4 floats so every
    // row base vl*CPAD*4 bytes is 16-byte aligned for the R48 float4
    // accesses (CPAD=129 gave 516B rows -> misaligned for vl%4!=0). 132 also
    // keeps the LDS.128 phases bank-conflict-free (row stride 132 floats
    // covers all 32 banks per 8-lane phase).
    constexpr int CPAD = 132;
    float* smem_m = scan_smem;                       // [2][128][MPAD] fp32
    float* smem_c0 = scan_smem + 2 * 128 * MPAD;     // [ROWS][CPAD] fp32
    float* smem_c1 = smem_c0 + ROWS * CPAD;          // [ROWS][CPAD] fp32
    float* smem_c2 = smem_c1 + ROWS * CPAD;          // [ROWS][CPAD] fp32
    int mbar_addr0 = 0, mbar_addr1 = 0;
    if (BULK) {
        // Two phase-toggled mbarriers (one per M panel) live after the c
        // panels (8B aligned: every preceding float offset is a multiple of
        // 4 floats, and 2*128*MPAD + 3*ROWS*CPAD is even).
        float* mbar = smem_c2 + ROWS * CPAD;
        mbar_addr0 = static_cast<int>(__cvta_generic_to_shared(mbar));
        mbar_addr1 = mbar_addr0 + 8;
        if (threadIdx.x == 0) {
            mbarrier_init(mbar_addr0, 1);
            mbarrier_init(mbar_addr1, 1);
            // generic-proxy init -> async-proxy (cp.async.bulk) use
            fence_async_shared();
        }
    }
    const int task = blockIdx.x;
    const int row_band = blockIdx.y;                 // 0..(128/ROWS-1): band rows
    const int seq_idx = seq_order[task / num_heads];
    const int head_idx = task % num_heads;
    const int t = threadIdx.x;
    const int vl = t >> 5;                           // 0..7; rows valid for vl<ROWS
    const int kl = t & 31;                           // k-lane: cols kl + i*32
    const int row0 = row_band * ROWS;
    const bool row_lane = vl < ROWS;

    float* smem_cur = smem_c0;
    float* smem_next = smem_c1;
    float* smem_mid = smem_c2;
    const long long slot0 = (long long)task * (long long)split_num_parts;
    // Pre-stage M_1 into buffer 0 ahead of the loop.
    if (BULK) {
        // One bulk copy per panel; the mbarrier wait replaces the ordering
        // __syncthreads. phase[p&1] carries the parity each panel's wait
        // expects next; every (arm, wait) pair toggles one phase once.
        if (t == 0) {
            mbarrier_arrive_expect_tx(mbar_addr0, 65536u);
            cp_async_bulk_g2s(static_cast<int>(__cvta_generic_to_shared(smem_m)),
                              map_state + (slot0 + 1) * 16384, 65536u, mbar_addr0);
        }
    } else {
        // Its pass-1 read is ordered by the __syncthreads below.
        const float4* msrc = reinterpret_cast<const float4*>(map_state + (slot0 + 1) * 16384);
        // 4096 float4s / 256 threads = 16 each; rows are 128 floats, so each
        // 32-float4 row lands bank-aligned with the +PAD trick below.
        #pragma unroll
        for (int i = 0; i < 16; i++) {
            const int f4idx = t + i * 256;
            *reinterpret_cast<float4*>(smem_m + (f4idx >> 5) * MPAD + (f4idx & 31) * 4) = msrc[f4idx];
        }
    }
    // Init: c_1 = end state of part 0 as computed by the main pass with the
    // real initial state (or a zero state when there is none). M_0 is never
    // needed: part 0 already absorbed the initial state directly.
    if (row_lane) {
        const float* s0src = split_state + slot0 * 16384 + (long long)(row0 + vl) * 128;
        *reinterpret_cast<float4*>(smem_cur + vl * CPAD + kl * 4) =
            *reinterpret_cast<const float4*>(s0src + kl * 4);
    }
    __syncthreads();

    const long long carry_task = (long long)seq_idx * (long long)num_heads + (long long)head_idx;
    float* cout = carry + carry_task * 16384 + (long long)(row0 + vl) * 128;
    const long long carry_part_stride = (long long)gridDim.x * 16384;

    // Stage the first pass's S_1 row into registers ahead of the loop.
    // Round-48 float4 restructure: thread (vl, kl) owns the four CONSECUTIVE
    // columns 4*kl..4*kl+3 for the matvec/mid-store/sp-stage/emit paths (the
    // c panels keep their [row][col] layout; only thread->column ownership
    // changed). Each kp step now costs one scalar LDS (broadcast) + one
    // LDS.128 + 4 FMA instead of 5 scalar LDS + 4 FMA (~2.5x fewer shared
    // ops; the LDS pipe was the per-pass bottleneck). Ownership by 4-column
    // groups stays bank-conflict-free (LDS.128 phases of 8 threads cover all
    // 32 banks exactly once). Per-element accumulation order kp=0..127 in
    // the same register is unchanged, so results are bit-exact vs round 45.
    float sp_reg[4] = {0.f, 0.f, 0.f, 0.f};
    if (row_lane) {
        const float* srow = split_state + (slot0 + 1) * 16384 + (long long)(row0 + vl) * 128;
        *reinterpret_cast<float4*>(sp_reg) = *reinterpret_cast<const float4*>(srow + kl * 4);
    }

    int smem_base = 0;
    int ph0 = 0, ph1 = 0;  // BULK mbarrier parity per M panel
    if (BULK) {
        smem_base = static_cast<int>(__cvta_generic_to_shared(smem_m));
    }
    for (int p = 1; p < split_num_parts; p++) {
        // Prefetch M_{p+1} into the alternate smem panel so its global loads
        // overlap this pass's matvec (the panel's previous readers finished
        // at last pass's trailing __syncthreads).
        if (BULK) {
            // Single-thread bulk issue: no per-thread LDG->STS round trip,
            // so no warp parks on a store-data scoreboard. WAR-safe: the arm
            // thread (t==0, a row-lane warp thread) can only reach pass p+1's
            // arm after this pass's matvec and trailing __syncthreads, so no
            // thread still reading this panel is overtaken by the next copy.
            if (p + 1 < split_num_parts && t == 0) {
                const int arm = p & 1;
                const int arm_addr = arm ? mbar_addr1 : mbar_addr0;
                mbarrier_arrive_expect_tx(arm_addr, 65536u);
                cp_async_bulk_g2s(smem_base + arm * 65536,
                                  map_state + (slot0 + (long long)(p + 1)) * 16384,
                                  65536u, arm_addr);
            }
        } else if (p + 1 < split_num_parts) {
            float* mdst = smem_m + (p & 1) * (128 * MPAD);
            const float4* msrc = reinterpret_cast<const float4*>(map_state + (slot0 + (long long)(p + 1)) * 16384);
            #pragma unroll
            for (int i = 0; i < 16; i++) {
                const int f4idx = t + i * 256;
                *reinterpret_cast<float4*>(mdst + (f4idx >> 5) * MPAD + (f4idx & 31) * 4) = msrc[f4idx];
            }
        }
        float acc[4];
        if (row_lane) {
            // Emit c_p (fp32) as the correction pass's initial state
            // (independent of the M prefetch; both overlap on the memory pipe).
            *reinterpret_cast<float4*>(cout + (long long)(p - 1) * carry_part_stride + kl * 4) =
                *reinterpret_cast<const float4*>(smem_cur + vl * CPAD + kl * 4);
            // c'[v,k] = S_p[v,k] + sum_k' c[v,k'] * M[k',k]. The S_p term was
            // staged one pass early.
            #pragma unroll
            for (int i = 0; i < 4; i++) acc[i] = sp_reg[i];
            // Prefetch the NEXT pass's additive row so the load overlaps this
            // pass's smem matvec.
            if (p + 1 < split_num_parts) {
                const float* srow = split_state + (slot0 + (long long)(p + 1)) * 16384 + (long long)(row0 + vl) * 128;
                *reinterpret_cast<float4*>(sp_reg) = *reinterpret_cast<const float4*>(srow + kl * 4);
            }
        }
        const float* mbuf = smem_m + ((p - 1) & 1) * (128 * MPAD);
        __syncthreads();  // c-panel ordering (smem_cur writes -> reads)
        if (BULK) {
            // Bulk-copy completion edge for the matvec reads below; the c-emit
            // STS above is already ordered vs the arm by program order.
            if ((p & 1) == 1) {
                mbarrier_wait(mbar_addr0, ph0);
                ph0 ^= 1;
            } else {
                mbarrier_wait(mbar_addr1, ph1);
                ph1 ^= 1;
            }
        }
        if (row_lane) {
            #pragma unroll 8
            for (int kp = 0; kp < 128; kp++) {
                const float a = smem_cur[vl * CPAD + kp];
                const float4 m4 = *reinterpret_cast<const float4*>(mbuf + kp * MPAD + kl * 4);
                acc[0] = fmaf(a, m4.x, acc[0]);
                acc[1] = fmaf(a, m4.y, acc[1]);
                acc[2] = fmaf(a, m4.z, acc[2]);
                acc[3] = fmaf(a, m4.w, acc[3]);
            }
            *reinterpret_cast<float4*>(smem_mid + vl * CPAD + kl * 4) =
                *reinterpret_cast<const float4*>(acc);
        }
        __syncthreads();
        float* tmp = smem_cur; smem_cur = smem_mid; smem_mid = smem_next; smem_next = tmp;
    }
}
// Round-51 BF16 M-panel scan variant (env-gated KDA_SCAN_BF16), v2 register-
// carry schedule. Same composition contract as kernel_flashkda_split_scan_m128
// (c_1 = S_0, c_{p+1} = S_p + M_p x c_p, fp32 carry + fp32 accumulation,
// per-element kp = 0..127 order) but:
//  * the staged M panel is the bf16 copy exported by the map pass: one 32KB
//    cp.async.bulk per panel (half the fp32 BULK bytes) on the same two-panel
//    mbarrier pipeline;
//  * the carry row lives in REGISTERS (thread = (row vl, col group kl) owns
//    c[row0+vl, 4*kl..4*kl+3]), so the per-pass A-operand exchange is one
//    __shfl_sync broadcast instead of two SMEM c-panel round trips + two
//    __syncthreads; the only barrier left per pass is the WAR guard for the
//    next bulk arm (a 128-thread __syncthreads);
//  * 128-thread CTAs (4 warps, every warp a row lane) -> SMEM 65552B -> 3
//    CTAs/SM.
// Per-pass measured cost drops from the LDS+double-sync latency chain to the
// shfl+LDS.64 issue stream. 8-lane LDS.64 phases at the 256B bf16 row pitch
// cover all 32 banks exactly once, so no M padding is needed.
__global__ __launch_bounds__(128) void kernel_flashkda_split_scan_bf16_m128(
    const __nv_bfloat16* __restrict__ initial_state,
    const float* __restrict__ split_state,
    const __nv_bfloat16* __restrict__ map_state_bf16,
    float* __restrict__ carry,
    const int* __restrict__ seq_order,
    int num_heads, int split_num_parts, int use_initial_state)
{
    extern __shared__ __align__(1024) float scan_smem[];
    __nv_bfloat16* smem_m = reinterpret_cast<__nv_bfloat16*>(scan_smem);  // [2][128][128] bf16
    int mbar_addr0, mbar_addr1;
    {
        float* mbar = scan_smem + 16384;               // 64KB panels -> offset 65536B
        mbar_addr0 = static_cast<int>(__cvta_generic_to_shared(mbar));
        mbar_addr1 = mbar_addr0 + 8;
        if (threadIdx.x == 0) {
            mbarrier_init(mbar_addr0, 1);
            mbarrier_init(mbar_addr1, 1);
            fence_async_shared();
        }
    }
    const int task = blockIdx.x;
    const int row_band = blockIdx.y;                   // 0..31: band owns rows 4*band..+3
    const int seq_idx = seq_order[task / num_heads];
    const int head_idx = task % num_heads;
    const int t = threadIdx.x;
    const int vl = t >> 5;                             // 0..3; row row0+vl
    const int kl = t & 31;                             // k-lane: cols 4*kl..4*kl+3
    const int row0 = row_band * 4;
    (void)use_initial_state;

    const long long slot0 = (long long)task * (long long)split_num_parts;
    // Pre-stage M_1 (32KB bf16) into panel 0 ahead of the loop.
    if (t == 0) {
        mbarrier_arrive_expect_tx(mbar_addr0, 32768u);
        cp_async_bulk_g2s(static_cast<int>(__cvta_generic_to_shared(smem_m)),
                          map_state_bf16 + (slot0 + 1) * 16384, 32768u, mbar_addr0);
    }
    // Register carry: c_1 = end state of part 0 (initial state absorbed by the
    // main pass); init to the part-0 row S_0, stage S_1 for the first pass.
    float creg[4], sp_reg[4];
    {
        const float* s0src = split_state + slot0 * 16384 + (long long)(row0 + vl) * 128;
        *reinterpret_cast<float4*>(creg) = *reinterpret_cast<const float4*>(s0src + kl * 4);
        const float* srow = split_state + (slot0 + 1) * 16384 + (long long)(row0 + vl) * 128;
        *reinterpret_cast<float4*>(sp_reg) = *reinterpret_cast<const float4*>(srow + kl * 4);
    }
    // The c-panel __syncthreads of the smem variant doubled as generic-proxy
    // visibility for the mbarrier init; with no c panels the first mbar wait
    // needs one ordering point for the init + arm above.
    __syncthreads();

    const long long carry_task = (long long)seq_idx * (long long)num_heads + (long long)head_idx;
    float* cout = carry + carry_task * 16384 + (long long)(row0 + vl) * 128;
    const long long carry_part_stride = (long long)gridDim.x * 16384;
    const int smem_base = static_cast<int>(__cvta_generic_to_shared(smem_m));
    int ph0 = 0, ph1 = 0;  // mbarrier parity per M panel
    for (int p = 1; p < split_num_parts; p++) {
        // Prefetch M_{p+1} (32KB bf16) into the alternate panel. WAR-safe:
        // panel p&1 was last read during pass p-1, whose trailing
        // __syncthreads every thread (including t==0) already passed.
        if (p + 1 < split_num_parts && t == 0) {
            const int arm = p & 1;
            const int arm_addr = arm ? mbar_addr1 : mbar_addr0;
            mbarrier_arrive_expect_tx(arm_addr, 32768u);
            cp_async_bulk_g2s(smem_base + arm * 32768,
                              map_state_bf16 + (slot0 + (long long)(p + 1)) * 16384,
                              32768u, arm_addr);
        }
        // Emit c_p (fp32, correction pass initial state) straight from the
        // register carry; no SMEM round trip.
        *reinterpret_cast<float4*>(cout + (long long)(p - 1) * carry_part_stride + kl * 4) =
            *reinterpret_cast<const float4*>(creg);
        float acc[4];
        #pragma unroll
        for (int i = 0; i < 4; i++) acc[i] = sp_reg[i];
        if (p + 1 < split_num_parts) {
            const float* srow = split_state + (slot0 + (long long)(p + 1)) * 16384 + (long long)(row0 + vl) * 128;
            *reinterpret_cast<float4*>(sp_reg) = *reinterpret_cast<const float4*>(srow + kl * 4);
        }
        const __nv_bfloat16* mbuf = smem_m + ((p - 1) & 1) * 16384;
        if ((p & 1) == 1) {
            mbarrier_wait(mbar_addr0, ph0);
            ph0 ^= 1;
        } else {
            mbarrier_wait(mbar_addr1, ph1);
            ph1 ^= 1;
        }
        // c'[v,k] = S_p[v,k] + sum_k' c[v,k'] * M_bf16[k',k]. The A operand
        // c[v,kp] is broadcast from lane (kp>>2) register creg[kp&3]; fully
        // unrolled so both indices are compile-time constants.
        #pragma unroll
        for (int kp = 0; kp < 128; kp++) {
            const float a = __shfl_sync(0xffffffffu, creg[kp & 3], kp >> 2);
            const uint2 m2 = *reinterpret_cast<const uint2*>(mbuf + kp * 128 + kl * 4);
            const float2 mx = __bfloat1622float2(*reinterpret_cast<const __nv_bfloat162*>(&m2.x));
            const float2 my = __bfloat1622float2(*reinterpret_cast<const __nv_bfloat162*>(&m2.y));
            acc[0] = fmaf(a, mx.x, acc[0]);
            acc[1] = fmaf(a, mx.y, acc[1]);
            acc[2] = fmaf(a, my.x, acc[2]);
            acc[3] = fmaf(a, my.y, acc[3]);
        }
        #pragma unroll
        for (int i = 0; i < 4; i++) creg[i] = acc[i];
        __syncthreads();  // WAR guard: pass p+1's bulk arm targets this panel
    }
}
extern "C" { // (templated scan kernel above lives in C++ linkage)

// ---------------------------------------------------------------------------
// Round-47 decoupled-lookback prefix scan (supervisor-mandated replacement
// for the R46 hierarchical affine scan). Same carry contract as
// kernel_flashkda_split_scan_m128 (carry[(p-1)*tasks + task] = c_p in fp32,
// c_1 = S_0, c_{p+1} = S_p + c_p x M_p) but resolved with the classic
// single-pass decoupled-lookback pattern instead of an O(P) serial chain or
// a materialized pair/group/seed hierarchy:
//   * grid = (tasks, P-1); CTA (task, q) with q = blockIdx.y + 1 publishes
//     the inclusive prefix c_q (its part's incoming state) to carry slot
//     (q-1) and releases flag[task*P + q] = 2;
//   * each part's local aggregate (S_p, M_p) is read straight from the
//     split_state/map_state exports of the main and map passes — NO extra
//     FP32 matrix compositions and NO extra workspace traffic;
//   * CTA q spins briefly on the immediate predecessor's flag (bounded
//     budget, so a not-yet-resident or timed-out predecessor can never
//     deadlock it), otherwise walks back to the largest published prefix
//     (or the always-ready base c_1 = S_0) and composes c forward over the
//     remaining per-part aggregates.
// Threads: 256 = 8 row-lanes x 32 k-groups; thread (vl, kl) owns the 16
// state rows [vl*16, +16) and column words kl*4 + j (j < 4). The c panel
// (128xMPAD floats) is a single buffer with an acc-register swap (matvec
// reads complete at the sync before the overwrite); M is double-buffered
// like the R45 serial scan so the next step's 64KB staging overlaps this
// step's matvec.
#define LOOKBACK_MPAD 132
#define LOOKBACK_SMEM_BYTES (2 * 128 * LOOKBACK_MPAD * 4 + 128 * LOOKBACK_MPAD * 4)

__global__ __launch_bounds__(256) void kernel_flashkda_split_lookback_m128(
    const float* __restrict__ split_state,
    const float* __restrict__ map_state,
    float* __restrict__ carry,
    int* __restrict__ flags,
    const int* __restrict__ seq_order,
    int num_heads, int split_num_parts)
{
    extern __shared__ __align__(1024) float lb_smem[];
    constexpr int MPAD = LOOKBACK_MPAD;
    float* smem_m = lb_smem;                  // [2][128][MPAD] fp32
    float* smem_c = lb_smem + 2 * 128 * MPAD; // [128][MPAD] fp32
    __shared__ int base_j_smem;
    const int task = blockIdx.x;
    const int q = (int)blockIdx.y + 1;        // part whose prefix c_q we emit
    const int P = split_num_parts;
    const int seq_idx = seq_order[task / num_heads];
    const int head_idx = task % num_heads;
    const int t = (int)threadIdx.x;
    const int vl = t >> 5;                    // 0..7
    const int kl = t & 31;
    const long long slot0 = (long long)task * (long long)P;

    // ---- Lookback: largest j in [1, q-1] with a published inclusive prefix.
    // Bounded spin on the immediate predecessor, one pass over older flags.
    if (t == 0) {
        int j = 0;
        const int jj = q - 1;
        if (jj >= 1) {
            int* fp = flags + slot0;
            const unsigned long long t0 = clock64();
            const unsigned long long BUDGET = 60000000ull;  // ~30us @ 2GHz
            bool got = false;
            while (atomicAdd(fp + jj, 0) < 2) {
                if (clock64() - t0 > BUDGET) break;
                __nanosleep(200);
            }
            if (atomicAdd(fp + jj, 0) >= 2) {
                j = jj;
                got = true;
            }
            if (!got) {
                for (int jp = q - 2; jp >= 1; jp--) {
                    if (atomicAdd(fp + jp, 0) >= 2) { j = jp; break; }
                }
            }
        }
        base_j_smem = j;
    }
    __syncthreads();
    const int base_j = base_j_smem;           // prefix index we start from
    const int ci0 = (base_j >= 1) ? base_j : 1;  // c_{ci0} is the base value
    __threadfence();  // acquire: the flag atomics above observed carry data
                      // published by other CTAs with release semantics

    // ---- Init c panel with the base prefix value.
    // c_1 = S_0 (split_state slot 0); c_j (j >= 1) = carry slot (j-1).
    const long long carry_part_stride = (long long)gridDim.x * 16384;
    const long long carry_task = (long long)seq_idx * (long long)num_heads + (long long)head_idx;
    {
        const float* csrc = (base_j >= 1)
            ? (carry + (long long)(base_j - 1) * carry_part_stride + carry_task * 16384)
            : (split_state + slot0 * 16384);
        #pragma unroll
        for (int r = 0; r < 16; r++) {
            *reinterpret_cast<float4*>(smem_c + (vl * 16 + r) * MPAD + kl * 4) =
                *reinterpret_cast<const float4*>(csrc + (vl * 16 + r) * 128 + kl * 4);
        }
    }
    // ---- Stage M_{ci0} into buffer 0 (plain LDG->STS; R45-proven pattern).
    if (ci0 < q) {
        const float4* msrc = reinterpret_cast<const float4*>(map_state + (slot0 + ci0) * 16384);
        #pragma unroll
        for (int i = 0; i < 16; i++) {
            const int f4idx = t + i * 256;
            *reinterpret_cast<float4*>(smem_m + (f4idx >> 5) * MPAD + (f4idx & 31) * 4) = msrc[f4idx];
        }
    }
    __syncthreads();

    // ---- Forward composition: for i = ci0 .. q-1, c = S_i + c x M_i.
    for (int i = ci0; i < q; i++) {
        const int par = (i - ci0) & 1;
        const float* mbuf = smem_m + par * (128 * MPAD);
        // acc = S_i row slice (16 rows x 4 contiguous cols)
        float acc[16][4];
        {
            const float* srow = split_state + (slot0 + i) * 16384 + (vl * 16) * 128 + kl * 4;
            #pragma unroll
            for (int r = 0; r < 16; r++) {
                *reinterpret_cast<float4*>(&acc[r][0]) =
                    *reinterpret_cast<const float4*>(srow + r * 128);
            }
        }
        // c'[v,k] += sum_k' c[v,k'] * M[k',k]; the M row float4 is hoisted
        // across the 16 owned rows; c words are warp-broadcast.
        #pragma unroll 8
        for (int kp = 0; kp < 128; kp++) {
            const float4 m4 = *reinterpret_cast<const float4*>(mbuf + kp * MPAD + kl * 4);
            const float* crow = smem_c + vl * 16 * MPAD + kp;
            #pragma unroll
            for (int r = 0; r < 16; r++) {
                const float a = crow[r * MPAD];
                acc[r][0] = fmaf(a, m4.x, acc[r][0]);
                acc[r][1] = fmaf(a, m4.y, acc[r][1]);
                acc[r][2] = fmaf(a, m4.z, acc[r][2]);
                acc[r][3] = fmaf(a, m4.w, acc[r][3]);
            }
        }
        __syncthreads();  // all c-panel and M-panel reads retired
        // Swap acc into the c panel and stage M_{i+1} into the other buffer.
        #pragma unroll
        for (int r = 0; r < 16; r++) {
            *reinterpret_cast<float4*>(smem_c + (vl * 16 + r) * MPAD + kl * 4) =
                *reinterpret_cast<const float4*>(&acc[r][0]);
        }
        if (i + 1 < q) {
            float* mdst = smem_m + (1 - par) * (128 * MPAD);
            const float4* msrc = reinterpret_cast<const float4*>(map_state + (slot0 + i + 1) * 16384);
            #pragma unroll
            for (int ii = 0; ii < 16; ii++) {
                const int f4idx = t + ii * 256;
                *reinterpret_cast<float4*>(mdst + (f4idx >> 5) * MPAD + (f4idx & 31) * 4) = msrc[f4idx];
            }
        }
        __syncthreads();  // c panel and next M visible
    }

    // ---- Publish: carry slot (q-1) = c_q, then release the flag.
    {
        float* cdst = carry + (long long)(q - 1) * carry_part_stride + carry_task * 16384;
        #pragma unroll
        for (int r = 0; r < 16; r++) {
            *reinterpret_cast<float4*>(cdst + (vl * 16 + r) * 128 + kl * 4) =
                *reinterpret_cast<const float4*>(smem_c + (vl * 16 + r) * MPAD + kl * 4);
        }
    }
    __threadfence();
    __syncthreads();
    if (t == 0) atomicExch(flags + slot0 + q, 2);
}

// Split-out add (round 32): folds the correction pass's scratch-stored carry
// contributions into out over the full-chunk token rows of parts [1, P).
// The fixup TMA path stores 32-token-aligned full chunks starting at part 1's
// first token (cpp*32 per sequence); partial tail chunks still accumulate
// directly into out in the fixup kernel scalar path, so the add range stops
// at the last full chunk row (fc*32). Window math matches KDA_SPLIT_WINDOW.
__global__ void __launch_bounds__(256)
kernel_flashkda_split_out_add_m128(const __nv_bfloat16* __restrict__ scratch,
                                   __nv_bfloat16* __restrict__ out,
                                   long long tokens_per_seq, int num_seqs, int num_parts,
                                   int num_heads) {
    const long long vecs_per_token = (long long)num_heads * 16;  // 128 bf16 = 16 uint4
    const long long i = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    const long long total_vec = tokens_per_seq * (long long)num_seqs * vecs_per_token;
    const long long stride = (long long)gridDim.x * blockDim.x;
    // Split-window bookkeeping for PART 1's first full-chunk row and the last
    // full chunk row (identical for every fixed-layout sequence).
    const long long fc = tokens_per_seq / 32;
    if (fc == 0) return;
    const long long cpp = (fc + num_parts - 1) / num_parts;
    const long long add_lo = cpp * 32;
    const long long add_hi = fc * 32;
    for (long long e = i; e < total_vec; e += stride) {
        const long long token = e / vecs_per_token;
        const long long st = token - (token / tokens_per_seq) * tokens_per_seq;
        if (st < add_lo || st >= add_hi) {
            continue;
        }
        const uint4 s4 = reinterpret_cast<const uint4*>(scratch)[e];
        uint4 o4 = reinterpret_cast<uint4*>(out)[e];
        __nv_bfloat162* sp = reinterpret_cast<__nv_bfloat162*>(const_cast<uint4*>(&s4));
        __nv_bfloat162* op = reinterpret_cast<__nv_bfloat162*>(&o4);
        #pragma unroll
        for (int h = 0; h < 4; h++) {
            op[h] = __hadd2(op[h], sp[h]);
        }
        reinterpret_cast<uint4*>(out)[e] = o4;
    }
}

} // extern "C"

// clang-format on
